import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
    )

    header = next(records, None)
    if header is None:
        return {"columns": [], "rows": []}

    # This format has one column. Keep extra fields in that cell rather
    # than dropping text, and preserve blank and comment-like records.
    return {
        "columns": [";".join(header)],
        "rows": [[";".join(record)] for record in records],
    }
